// Generated from ecma262/spec.html — do not edit by hand.
const sections = {"1":"<p>Shared memory accesses (reads and writes) are divided into two groups, atomic accesses and data accesses, defined below. Atomic accesses are sequentially consistent, i.e., there is a strict total ordering of events agreed upon by all <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in an <emu-xref href=\"/executable-code-and-execution-contexts#sec-agent-clusters\"><a href=\"/executable-code-and-execution-contexts#sec-agent-clusters\">agent cluster</a></emu-xref>. Non-atomic accesses do not have a strict total ordering agreed upon by all <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref>, i.e., unordered.</p>\n    <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n      <p>No orderings weaker than sequentially consistent and stronger than unordered, such as release-acquire, are supported.</p>\n    </div></emu-note>\n    <p>A <dfn variants=\"Shared Data Block events\">Shared Data Block event</dfn> is either a <dfn>ReadSharedMemory</dfn>, <dfn>WriteSharedMemory</dfn>, or <dfn>ReadModifyWriteSharedMemory</dfn> <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref>. A <dfn variants=\"read events\">read event</dfn> is either a ReadSharedMemory or a ReadModifyWriteSharedMemory. A <dfn variants=\"write events\">write event</dfn> is either a WriteSharedMemory or a ReadModifyWriteSharedMemory.</p>\n\n    <emu-table id=\"table-readsharedmemory-fields\" caption=\"ReadSharedMemory Event Fields\" data-num=\"89\">\n      <table>\n        <thead>\n          <tr>\n            <th>Field Name</th>\n            <th>Value</th>\n            <th>Meaning</th>\n          </tr>\n        </thead>\n        <tr>\n          <td><var class=\"field\">[[Order]]</var></td>\n          <td><emu-const>seq-cst</emu-const> or <emu-const>unordered</emu-const></td>\n          <td>The weakest ordering guaranteed by the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> for the event.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[NoTear]]</var></td>\n          <td>a Boolean</td>\n          <td>Whether this event is allowed to read from multiple write events with equal memory range as this event.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[Block]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">Shared Data Block</a></emu-xref></td>\n          <td>The block the event operates on.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ByteIndex]]</var></td>\n          <td>a non-negative <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref></td>\n          <td>The byte address of the read in <var class=\"field\">[[Block]]</var>.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ElementSize]]</var></td>\n          <td>a non-negative <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref></td>\n          <td>The size of the read.</td>\n        </tr>\n      </table>\n    </emu-table>\n\n    <emu-table id=\"table-writesharedmemory-fields\" caption=\"WriteSharedMemory Event Fields\" data-num=\"90\">\n      <table>\n        <thead>\n          <tr>\n            <th>Field Name</th>\n            <th>Value</th>\n            <th>Meaning</th>\n          </tr>\n        </thead>\n        <tr>\n          <td><var class=\"field\">[[Order]]</var></td>\n          <td><emu-const>seq-cst</emu-const>, <emu-const>unordered</emu-const>, or <emu-const>init</emu-const></td>\n          <td>The weakest ordering guaranteed by the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> for the event.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[NoTear]]</var></td>\n          <td>a Boolean</td>\n          <td>Whether this event is allowed to be read from multiple read events with equal memory range as this event.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[Block]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">Shared Data Block</a></emu-xref></td>\n          <td>The block the event operates on.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ByteIndex]]</var></td>\n          <td>a non-negative <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref></td>\n          <td>The byte address of the write in <var class=\"field\">[[Block]]</var>.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ElementSize]]</var></td>\n          <td>a non-negative <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref></td>\n          <td>The size of the write.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[Payload]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref></td>\n          <td>The <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref> to be read by other events.</td>\n        </tr>\n      </table>\n    </emu-table>\n\n    <emu-table id=\"table-rmwsharedmemory-fields\" caption=\"ReadModifyWriteSharedMemory Event Fields\" data-num=\"91\">\n      <table>\n        <thead>\n          <tr>\n            <th>Field Name</th>\n            <th>Value</th>\n            <th>Meaning</th>\n          </tr>\n        </thead>\n        <tr>\n          <td><var class=\"field\">[[Order]]</var></td>\n          <td><emu-const>seq-cst</emu-const></td>\n          <td>Read-modify-write events are always sequentially consistent.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[NoTear]]</var></td>\n          <td><emu-val>true</emu-val></td>\n          <td>Read-modify-write events cannot tear.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[Block]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">Shared Data Block</a></emu-xref></td>\n          <td>The block the event operates on.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ByteIndex]]</var></td>\n          <td>a non-negative <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref></td>\n          <td>The byte address of the read-modify-write in <var class=\"field\">[[Block]]</var>.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ElementSize]]</var></td>\n          <td>a non-negative <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref></td>\n          <td>The size of the read-modify-write.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[Payload]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref></td>\n          <td>The <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref> to be passed to <var class=\"field\">[[ModifyOp]]</var>.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ModifyOp]]</var></td>\n          <td>a <emu-xref href=\"/structured-data#sec-arraybuffer-notation\"><a href=\"/structured-data#sec-arraybuffer-notation\">read-modify-write modification function</a></emu-xref></td>\n          <td>An <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref> that returns a modified <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref> from a read <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref> and <var class=\"field\">[[Payload]]</var>.</td>\n        </tr>\n      </table>\n    </emu-table>\n\n    <p>Shared Data Block events are introduced to <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <emu-xref href=\"/memory-model#sec-agent-event-records\"><a href=\"/memory-model#sec-agent-event-records\">Agent Events Records</a></emu-xref> by <emu-xref href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\"><a href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\">abstract operations</a></emu-xref> or by methods on the Atomics object. Some operations also introduce <dfn variants=\"Synchronize,Synchronize event\">Synchronize events</dfn>, which have no fields and exist purely to directly constrain the permitted orderings of other events. And finally, there are <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref>-specific events. A <dfn variants=\"Memory events\">Memory event</dfn> is either a Shared Data Block event, Synchronize event, or such a <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref>-specific event.</p>\n    <p>Let the <dfn variants=\"memory ranges\">memory range</dfn> of a Shared Data Block event <var>e</var> be the Set of all <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integers</a></emu-xref> in the <emu-xref href=\"/notational-conventions#interval\"><a href=\"/notational-conventions#interval\">interval</a></emu-xref> from <var>e</var>.<var class=\"field\">[[ByteIndex]]</var> (inclusive) to <var>e</var>.<var class=\"field\">[[ByteIndex]]</var> + <var>e</var>.<var class=\"field\">[[ElementSize]]</var> (exclusive). Two events' memory ranges are equal when the events have the same <var class=\"field\">[[Block]]</var>, <var class=\"field\">[[ByteIndex]]</var>, and <var class=\"field\">[[ElementSize]]</var>. Two events' memory ranges are overlapping when the events have the same <var class=\"field\">[[Block]]</var>, the ranges are not equal, and their intersection is non-empty. Two events' memory ranges are disjoint when the events do not have the same <var class=\"field\">[[Block]]</var> or their ranges are neither equal nor overlapping.</p>\n    <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n      <p>Examples of <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref>-specific synchronizing events that should be accounted for are: sending a SharedArrayBuffer from one <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> to another (e.g., by <code>postMessage</code> in a browser), starting and stopping <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref>, and communicating within the <emu-xref href=\"/executable-code-and-execution-contexts#sec-agent-clusters\"><a href=\"/executable-code-and-execution-contexts#sec-agent-clusters\">agent cluster</a></emu-xref> via channels other than shared memory. For a particular execution <var>execution</var>, those events are provided by the <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref> via the <emu-xref href=\"/memory-model#sec-host-synchronizes-with\"><a href=\"/memory-model#sec-host-synchronizes-with\">host-synchronizes-with</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">strict partial order</a></emu-xref>. Additionally, <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">hosts</a></emu-xref> can add <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref>-specific synchronizing events to <var>execution</var>.<var class=\"field\">[[EventList]]</var> so as to participate in the <emu-xref href=\"/memory-model#sec-agent-order\"><a href=\"/memory-model#sec-agent-order\">is-agent-order-before</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref>.</p>\n    </div></emu-note>\n    <p>Events are ordered within <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate executions</a></emu-xref> by the relations defined below.</p>\n  ","2":"<p>An <dfn variants=\"Agent Events Records\">Agent Events Record</dfn> is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> with the following fields.</p>\n    <emu-table id=\"table-agent-events-records\" caption=\"Agent Events Record Fields\" data-num=\"92\">\n      <table>\n        <thead>\n          <tr>\n            <th>Field Name</th>\n            <th>Value</th>\n            <th>Meaning</th>\n          </tr>\n        </thead>\n        <tr>\n          <td><var class=\"field\">[[AgentSignifier]]</var></td>\n          <td>an <emu-xref href=\"/executable-code-and-execution-contexts#sec-agents\"><a href=\"/executable-code-and-execution-contexts#sec-agents\">agent signifier</a></emu-xref></td>\n          <td>The <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> whose evaluation resulted in this ordering.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[EventList]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref></td>\n          <td>Events are appended to the list during evaluation.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[AgentSynchronizesWith]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of pairs of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Synchronize events</a></emu-xref></td>\n          <td><emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Synchronize</a></emu-xref> relationships introduced by the operational semantics.</td>\n        </tr>\n      </table>\n    </emu-table>\n  ","3":"<p>A <dfn variants=\"Chosen Value Records\">Chosen Value Record</dfn> is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> with the following fields.</p>\n    <emu-table id=\"table-chosen-value-records\" caption=\"Chosen Value Record Fields\" data-num=\"93\">\n      <table>\n        <thead>\n          <tr>\n            <th>Field Name</th>\n            <th>Value</th>\n            <th>Meaning</th>\n          </tr>\n        </thead>\n        <tr>\n          <td><var class=\"field\">[[Event]]</var></td>\n          <td>a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block event</a></emu-xref></td>\n          <td>The <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event that was introduced for this chosen value.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ChosenValue]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref></td>\n          <td>The bytes that were nondeterministically chosen during evaluation.</td>\n        </tr>\n      </table>\n    </emu-table>\n  ","4":"<p>A <dfn variants=\"candidate executions\">candidate execution</dfn> of the evaluation of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-agent-clusters\"><a href=\"/executable-code-and-execution-contexts#sec-agent-clusters\">agent cluster</a></emu-xref> is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> with the following fields.</p>\n    <emu-table id=\"table-candidate-execution-records\" caption=\"Candidate Execution Record Fields\" data-num=\"94\">\n      <table>\n        <thead>\n          <tr>\n            <th>Field Name</th>\n            <th>Value</th>\n            <th>Meaning</th>\n          </tr>\n        </thead>\n        <tr>\n          <td><var class=\"field\">[[EventsRecords]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/memory-model#sec-agent-event-records\"><a href=\"/memory-model#sec-agent-event-records\">Agent Events Records</a></emu-xref></td>\n          <td>Maps an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> to <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Lists</a></emu-xref> of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> appended during the evaluation.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ChosenValues]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/memory-model#sec-chosen-value-records\"><a href=\"/memory-model#sec-chosen-value-records\">Chosen Value Records</a></emu-xref></td>\n          <td>Maps <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> events to the <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref> chosen during the evaluation.</td>\n        </tr>\n      </table>\n    </emu-table>\n\n    <p>An <dfn variants=\"empty candidate executions\">empty candidate execution</dfn> is a candidate execution <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> whose fields are empty <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Lists</a></emu-xref>.</p>\n  ","5":"","6":"<p>The following relations and mathematical functions are parameterized over a particular <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> and order its <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref>.</p>\n\n    ","7":"","8":"<p>For an execution <var>execution</var> and events <var>eventA</var> and <var>eventB</var> that are contained in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>), <var>eventA</var> and <var>eventB</var> are in a <em>race</em> if the following algorithm returns <emu-val>true</emu-val>.</p>\n    <emu-alg><ol><li>If <var>eventA</var> and <var>eventB</var> are not the same <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block event</a></emu-xref>, then<ol><li>If it is not the case that both <var>eventA</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>eventB</var> in <var>execution</var> and <var>eventB</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>eventA</var> in <var>execution</var>, then<ol><li>If <var>eventA</var> is either a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event, <var>eventB</var> is either a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event, and <var>eventA</var> and <var>eventB</var> do not have disjoint <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>, then<ol><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></li><li>If <var>eventA</var> <emu-xref href=\"/memory-model#sec-reads-from\"><a href=\"/memory-model#sec-reads-from\">reads-from</a></emu-xref> <var>eventB</var> in <var>execution</var> or <var>eventB</var> <emu-xref href=\"/memory-model#sec-reads-from\"><a href=\"/memory-model#sec-reads-from\">reads-from</a></emu-xref> <var>eventA</var> in <var>execution</var>, then<ol><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></li></ol></li></ol></li><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n  ","9":"<p>For an execution <var>execution</var> and events <var>eventA</var> and <var>eventB</var> that are contained in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>), <var>eventA</var> and <var>eventB</var> are in a <dfn>data race</dfn> if the following algorithm returns <emu-val>true</emu-val>.</p>\n    <emu-alg><ol><li>If <var>eventA</var> and <var>eventB</var> are in a <emu-xref href=\"#sec-races\"><a href=\"/memory-model#sec-races\">race</a></emu-xref> in <var>execution</var>, then<ol><li>If <var>eventA</var>.<var class=\"field\">[[Order]]</var> is not <emu-const>seq-cst</emu-const> or <var>eventB</var>.<var class=\"field\">[[Order]]</var> is not <emu-const>seq-cst</emu-const>, then<ol><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></li><li>If <var>eventA</var> and <var>eventB</var> have overlapping <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>, then<ol><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></li></ol></li><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n  ","10":"<p>An execution <var>execution</var> is <dfn>data race free</dfn> if there are no two events in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>) that are in a <emu-xref href=\"/memory-model#sec-data-races\"><a href=\"/memory-model#sec-data-races\">data race</a></emu-xref>.</p>\n    <p>A program is data race free if all its executions are data race free.</p>\n    <p>The <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> guarantees sequential consistency of all events for data race free programs.</p>\n  ","11":"<emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n      <p>The following are guidelines for ECMAScript programmers working with shared memory.</p>\n      <p>We recommend programs be kept <emu-xref href=\"/memory-model#sec-data-race-freedom\"><a href=\"/memory-model#sec-data-race-freedom\">data race free</a></emu-xref>, i.e., make it so that it is impossible for there to be concurrent non-atomic operations on the same memory location. <emu-xref href=\"/memory-model#sec-data-race-freedom\"><a href=\"/memory-model#sec-data-race-freedom\">Data race free</a></emu-xref> programs have interleaving semantics where each step in the evaluation semantics of each <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> are interleaved with each other. For <emu-xref href=\"/memory-model#sec-data-race-freedom\"><a href=\"/memory-model#sec-data-race-freedom\">data race free</a></emu-xref> programs, it is not necessary to understand the details of the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref>. The details are unlikely to build intuition that will help one to better write ECMAScript.</p>\n      <p>More generally, even if a program is not <emu-xref href=\"/memory-model#sec-data-race-freedom\"><a href=\"/memory-model#sec-data-race-freedom\">data race free</a></emu-xref> it may have predictable behaviour, so long as atomic operations are not involved in any data races and the operations that race all have the same access size. The simplest way to arrange for atomics not to be involved in races is to ensure that different memory cells are used by atomic and non-atomic operations and that atomic accesses of different sizes are not used to access the same cells at the same time. Effectively, the program should treat shared memory as strongly typed as much as possible. One still cannot depend on the ordering and timing of non-atomic accesses that race, but if memory is treated as strongly typed the racing accesses will not “tear” (bits of their values will not be mixed).</p>\n    </div></emu-note>\n\n    <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n      <p>The following are guidelines for ECMAScript implementers writing compiler transformations for programs using shared memory.</p>\n      <p>It is desirable to allow most program transformations that are valid in a single-<emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> setting in a multi-<emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> setting, to ensure that the performance of each <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> in a multi-<emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> program is as good as it would be in a single-<emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> setting. Frequently these transformations are hard to judge. We outline some rules about program transformations that are intended to be taken as normative (in that they are implied by the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> or stronger than what the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> implies) but which are likely not exhaustive. These rules are intended to apply to program transformations that precede the introductions of the <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> that make up the <emu-xref href=\"/memory-model#sec-agent-order\"><a href=\"/memory-model#sec-agent-order\">is-agent-order-before</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref>.</p>\n      <p>Let an <dfn variants=\"agent-order slices\">agent-order slice</dfn> be the subset of the <emu-xref href=\"/memory-model#sec-agent-order\"><a href=\"/memory-model#sec-agent-order\">is-agent-order-before</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> pertaining to a single <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>.</p>\n      <p>Let <dfn>possible read values</dfn> of a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">read event</a></emu-xref> be the set of all values of <emu-xref aoid=\"ValueOfReadEvent\"><a href=\"/memory-model#sec-valueofreadevent\">ValueOfReadEvent</a></emu-xref> for that event across all valid executions.</p>\n      <p>Any transformation of an agent-order slice that is valid in the absence of shared memory is valid in the presence of shared memory, with the following exceptions.</p>\n      <ul>\n        <li>\n          <p><em>Atomics are carved in stone</em>: Program transformations must not cause any <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block events</a></emu-xref> whose <var class=\"field\">[[Order]]</var> is <emu-const>seq-cst</emu-const> to be removed from the <emu-xref href=\"/memory-model#sec-agent-order\"><a href=\"/memory-model#sec-agent-order\">is-agent-order-before</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref>, nor to be reordered with respect to each other, nor to be reordered inside an agent-order slice with respect to events whose <var class=\"field\">[[Order]]</var> is <emu-const>unordered</emu-const>.</p>\n          <p>(In practice, the prohibition on reorderings forces a compiler to assume that every <emu-const>seq-cst</emu-const> operation is a synchronization and included in the final <emu-xref href=\"/memory-model#sec-memory-order\"><a href=\"/memory-model#sec-memory-order\">is-memory-order-before</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref>, which it would usually have to assume anyway in the absence of inter-<emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> program analysis. It also forces the compiler to assume that every call where the callee's effects on the memory-order are unknown may contain <emu-const>seq-cst</emu-const> operations.)</p>\n        </li>\n        <li>\n          <p><em>Reads must be stable</em>: Any given shared memory read must only observe a single value in an execution.</p>\n          <p>(For example, if what is semantically a single read in the program is executed multiple times then the program is subsequently allowed to observe only one of the values read. A transformation known as rematerialization can violate this rule.)</p>\n        </li>\n        <li>\n          <p><em>Writes must be stable</em>: All observable writes to shared memory must follow from program semantics in an execution.</p>\n          <p>(For example, a transformation may not introduce certain observable writes, such as by using read-modify-write operations on a larger location to write a smaller datum, writing a value to memory that the program could not have written, or writing a just-read value back to the location it was read from, if that location could have been overwritten by another <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> after the read.)</p>\n        </li>\n        <li>\n          <p><em>Possible read values must be non-empty</em>: Program transformations cannot cause the possible read values of a shared memory read to become empty.</p>\n          <p>(Counterintuitively, this rule in effect restricts transformations on writes, because writes have force in <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> insofar as to be read by <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">read events</a></emu-xref>. For example, writes may be moved and coalesced and sometimes reordered between two <emu-const>seq-cst</emu-const> operations, but the transformation may not remove every write that updates a location; some write must be preserved.)</p>\n        </li>\n      </ul>\n      <p>Examples of transformations that remain valid are: merging multiple non-atomic reads from the same location, reordering non-atomic reads, introducing speculative non-atomic reads, merging multiple non-atomic writes to the same location, reordering non-atomic writes to different locations, and hoisting non-atomic reads out of loops even if that affects termination. Note in general that aliased <emu-xref href=\"/ordinary-and-exotic-objects-behaviours#typedarray\"><a href=\"/ordinary-and-exotic-objects-behaviours#typedarray\">TypedArrays</a></emu-xref> make it hard to prove that locations are different.</p>\n    </div></emu-note>\n\n    <emu-note data-num=\"3\"><span class=\"note\">Note 3</span><div class=\"note-contents\">\n      <p>The following are guidelines for ECMAScript implementers generating machine code for shared memory accesses.</p>\n      <p>For architectures with memory models no weaker than those of ARM or Power, non-atomic stores and loads may be compiled to bare stores and loads on the target architecture. Atomic stores and loads may be compiled down to instructions that guarantee sequential consistency. If no such instructions exist, memory barriers are to be employed, such as placing barriers on both sides of a bare store or load. Read-modify-write operations may be compiled to read-modify-write instructions on the target architecture, such as <code>LOCK</code>-prefixed instructions on x86, load-exclusive/store-exclusive instructions on ARM, and load-link/store-conditional instructions on Power.</p>\n      <p>Specifically, the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> is intended to allow code generation as follows.</p>\n      <ul>\n        <li>Every atomic operation in the program is assumed to be necessary.</li>\n        <li>Atomic operations are never rearranged with each other or with non-atomic operations.</li>\n        <li>Functions are always assumed to perform atomic operations.</li>\n        <li>Atomic operations are never implemented as read-modify-write operations on larger data, but as non-lock-free atomics if the platform does not have atomic operations of the appropriate size. (We already assume that every platform has normal memory access operations of every interesting size.)</li>\n      </ul>\n      <p>Naive code generation uses these patterns:</p>\n      <ul>\n        <li>Regular loads and stores compile to single load and store instructions.</li>\n        <li>Lock-free atomic loads and stores compile to a full (sequentially consistent) fence, a regular load or store, and a full fence.</li>\n        <li>Lock-free atomic read-modify-write accesses compile to a full fence, an atomic read-modify-write instruction sequence, and a full fence.</li>\n        <li>Non-lock-free atomics compile to a spinlock acquire, a full fence, a series of non-atomic load and store instructions, a full fence, and a spinlock release.</li>\n      </ul>\n      <p>That mapping is correct so long as an atomic operation on a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory range</a></emu-xref> does not race with a non-atomic write or with an atomic operation of different size. However, that is all we need: the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> effectively demotes the atomic operations involved in a race to non-atomic status. On the other hand, the naive mapping is quite strong: it allows atomic operations to be used as sequentially consistent fences, which the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> does not actually guarantee.</p>\n      <p>Local improvements to those basic patterns are also allowed, subject to the constraints of the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref>. For example:</p>\n      <ul>\n        <li>There are obvious platform-dependent improvements that remove redundant fences. For example, on x86 the fences around lock-free atomic loads and stores can always be omitted except for the fence following a store, and no fence is needed for lock-free read-modify-write instructions, as these all use <code>LOCK</code>-prefixed instructions. On many platforms there are fences of several strengths, and weaker fences can be used in certain contexts without destroying sequential consistency.</li>\n        <li>Most modern platforms support lock-free atomics for all the data sizes required by ECMAScript atomics. Should non-lock-free atomics be needed, the fences surrounding the body of the atomic operation can usually be folded into the lock and unlock steps. The simplest solution for non-lock-free atomics is to have a single lock word per SharedArrayBuffer.</li>\n        <li>There are also more complicated platform-dependent local improvements, requiring some code analysis. For example, two back-to-back fences often have the same effect as a single fence, so if code is generated for two atomic operations in sequence, only a single fence need separate them. On x86, even a single fence separating atomic stores can be omitted, as the fence following a store is only needed to separate the store from a subsequent load.</li>\n      </ul>\n    </div></emu-note>\n  ","":"<p>The memory consistency model, or <dfn>memory model</dfn>, specifies the possible orderings of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block events</a></emu-xref>, arising via accessing <emu-xref href=\"/ordinary-and-exotic-objects-behaviours#typedarray\"><a href=\"/ordinary-and-exotic-objects-behaviours#typedarray\">TypedArray</a></emu-xref> instances backed by a SharedArrayBuffer and via methods on the Atomics object. When the program has no data races (defined below), the ordering of events appears as sequentially consistent, i.e., as an interleaving of actions from each <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>. When the program has data races, shared memory operations may appear sequentially inconsistent. For example, programs may exhibit causality-violating behaviour and other astonishments. These astonishments arise from compiler transforms and the design of CPUs (e.g., out-of-order execution and speculation). The memory model defines both the precise conditions under which a program exhibits sequentially consistent behaviour as well as the possible values read from data races. To wit, there is no undefined behaviour.</p>\n  <p>The memory model is defined as relational constraints on <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> introduced by <emu-xref href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\"><a href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\">abstract operations</a></emu-xref> on SharedArrayBuffer or by methods on the Atomics object during an evaluation.</p>\n  <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n    <p>This section provides an axiomatic model on <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> introduced by the <emu-xref href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\"><a href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\">abstract operations</a></emu-xref> on SharedArrayBuffers. It bears stressing that the model is not expressible algorithmically, unlike the rest of this specification. The nondeterministic introduction of events by <emu-xref href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\"><a href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\">abstract operations</a></emu-xref> is the interface between the operational semantics of ECMAScript evaluation and the axiomatic semantics of the memory model. The semantics of these events is defined by considering graphs of all events in an evaluation. These are neither Static Semantics nor Runtime Semantics. There is no demonstrated algorithmic implementation, but instead a set of constraints that determine if a particular event graph is allowed or disallowed.</p>\n  </div></emu-note>\n\n  ","5.1":"<p>The abstract operation EventSet takes argument <var>execution</var> (a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref>) and returns a Set of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>events</var> be an empty Set.</li><li>For each <emu-xref href=\"/memory-model#sec-agent-event-records\"><a href=\"/memory-model#sec-agent-event-records\">Agent Events Record</a></emu-xref> <var>aer</var> of <var>execution</var>.<var class=\"field\">[[EventsRecords]]</var>, do<ol><li>For each <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory event</a></emu-xref> <var>event</var> of <var>aer</var>.<var class=\"field\">[[EventList]]</var>, do<ol><li>Add <var>event</var> to <var>events</var>.</li></ol></li></ol></li><li class=\"exit\">Return <var>events</var>.</li></ol></emu-alg>\n    ","5.2":"<p>The abstract operation SharedDataBlockEventSet takes argument <var>execution</var> (a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref>) and returns a Set of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block events</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>events</var> be an empty Set.</li><li>For each <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory event</a></emu-xref> <var>event</var> of <emu-xref aoid=\"EventSet\"><a href=\"/memory-model#sec-event-set\">EventSet</a></emu-xref>(<var>execution</var>), do<ol><li>If <var>event</var> is a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block event</a></emu-xref>, add <var>event</var> to <var>events</var>.</li></ol></li><li class=\"exit\">Return <var>events</var>.</li></ol></emu-alg>\n    ","5.3":"<p>The abstract operation HostEventSet takes argument <var>execution</var> (a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref>) and returns a Set of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li class=\"exit\">Return a new Set containing all elements of <emu-xref aoid=\"EventSet\"><a href=\"/memory-model#sec-event-set\">EventSet</a></emu-xref>(<var>execution</var>) that are not in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>).</li></ol></emu-alg>\n    ","5.4":"<p>The abstract operation ComposeWriteEventBytes takes arguments <var>execution</var> (a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref>), <var>byteIndex</var> (a non-negative <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref>), and <var>writes</var> (a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of either <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> events) and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>byteLocation</var> be <var>byteIndex</var>.</li><li>Let <var>bytesRead</var> be a new empty <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref>.</li><li>For each element <var>writeEvent</var> of <var>writes</var>, do<ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>writeEvent</var> has <var>byteLocation</var> in its <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory range</a></emu-xref>.</li><li>Let <var>payloadIndex</var> be <var>byteLocation</var> - <var>writeEvent</var>.<var class=\"field\">[[ByteIndex]]</var>.</li><li>If <var>writeEvent</var> is a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> event, then<ol><li>Let <var>byte</var> be <var>writeEvent</var>.<var class=\"field\">[[Payload]]</var>[<var>payloadIndex</var>].</li></ol></li><li>Else,<ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>writeEvent</var> is a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event.</li><li>Let <var>bytes</var> be <emu-xref aoid=\"ValueOfReadEvent\"><a href=\"/memory-model#sec-valueofreadevent\">ValueOfReadEvent</a></emu-xref>(<var>execution</var>, <var>writeEvent</var>).</li><li>Let <var>bytesModified</var> be <var>writeEvent</var>.<var class=\"field\">[[ModifyOp]]</var>(<var>bytes</var>, <var>writeEvent</var>.<var class=\"field\">[[Payload]]</var>).</li><li>Let <var>byte</var> be <var>bytesModified</var>[<var>payloadIndex</var>].</li></ol></li><li>Append <var>byte</var> to <var>bytesRead</var>.</li><li>Set <var>byteLocation</var> to <var>byteLocation</var> + 1.</li></ol></li><li class=\"exit\">Return <var>bytesRead</var>.</li></ol></emu-alg>\n      <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n        <p>The read-modify-write modification <var class=\"field\">[[ModifyOp]]</var> is given by the function properties on the Atomics object that introduce <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> events.</p>\n      </div></emu-note>\n      <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n        <p>This abstract operation composes a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">write events</a></emu-xref> into a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref>. It is used in the event semantics of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> and <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> events.</p>\n      </div></emu-note>\n    ","5.5":"<p>The abstract operation ValueOfReadEvent takes arguments <var>execution</var> (a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref>) and <var>readEvent</var> (a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event) and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">byte values</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>writes</var> be <emu-xref aoid=\"reads-bytes-from\"><a href=\"/memory-model#sec-reads-bytes-from\">reads-bytes-from</a></emu-xref>(<var>readEvent</var>) in <var>execution</var>.</li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>writes</var> is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> events with length equal to <var>readEvent</var>.<var class=\"field\">[[ElementSize]]</var>.</li><li class=\"exit\">Return <emu-xref aoid=\"ComposeWriteEventBytes\"><a href=\"/memory-model#sec-composewriteeventbytes\">ComposeWriteEventBytes</a></emu-xref>(<var>execution</var>, <var>readEvent</var>.<var class=\"field\">[[ByteIndex]]</var>, <var>writes</var>).</li></ol></emu-alg>\n    ","6.1":"<p>For a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, its <dfn>is-agent-order-before</dfn> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> is the <emu-xref href=\"/ecmascript-data-types-and-values#least-relation\"><a href=\"/ecmascript-data-types-and-values#least-relation\">least Relation</a></emu-xref> on <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> that satisfies the following.</p>\n      <ul>\n        <li>For events <var>eventA</var> and <var>eventB</var>, <var>eventA</var> is-agent-order-before <var>eventB</var> in <var>execution</var> if there is some <emu-xref href=\"/memory-model#sec-agent-event-records\"><a href=\"/memory-model#sec-agent-event-records\">Agent Events Record</a></emu-xref> <var>aer</var> in <var>execution</var>.<var class=\"field\">[[EventsRecords]]</var> such that <var>aer</var>.<var class=\"field\">[[EventList]]</var> contains both <var>eventA</var> and <var>eventB</var> and <var>eventA</var> is before <var>eventB</var> in <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> order of <var>aer</var>.<var class=\"field\">[[EventList]]</var>.</li>\n      </ul>\n\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>Each <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> introduces events in a per-<emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">strict total order</a></emu-xref> during the evaluation. This is the union of those <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">strict total orders</a></emu-xref>.</p>\n      </div></emu-note>\n    ","6.2":"<p>For a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, its <em>reads-bytes-from</em> function is a mathematical function mapping <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>) to <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Lists</a></emu-xref> of events in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>) that satisfies the following conditions.</p>\n      <ul>\n        <li>\n          <p>For each <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event <var>readEvent</var> in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>), reads-bytes-from(<var>readEvent</var>) in <var>execution</var> is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of length <var>readEvent</var>.<var class=\"field\">[[ElementSize]]</var> whose elements are <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> events <var>writes</var> such that all of the following are true.</p>\n          <ul>\n            <li>Each event <var>writeEvent</var> with index <var>i</var> in <var>writes</var> has <var>readEvent</var>.<var class=\"field\">[[ByteIndex]]</var> + <var>i</var> in its <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory range</a></emu-xref>.</li>\n            <li><var>result</var> is not in <var>writes</var>.</li>\n          </ul>\n        </li>\n      </ul>\n      <p>A <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> always admits a reads-bytes-from function.</p>\n    ","6.3":"<p>For a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, its <dfn>reads-from</dfn> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> is the <emu-xref href=\"/ecmascript-data-types-and-values#least-relation\"><a href=\"/ecmascript-data-types-and-values#least-relation\">least Relation</a></emu-xref> on <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> that satisfies the following.</p>\n      <ul>\n        <li>For events <var>readEvent</var> and <var>writeEvent</var>, <var>readEvent</var> reads-from <var>writeEvent</var> in <var>execution</var> if <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>) contains both <var>readEvent</var> and <var>writeEvent</var>, and <emu-xref aoid=\"reads-bytes-from\"><a href=\"/memory-model#sec-reads-bytes-from\">reads-bytes-from</a></emu-xref>(<var>readEvent</var>) in <var>execution</var> contains <var>writeEvent</var>.</li>\n      </ul>\n    ","6.4":"<p>For a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, its <dfn>host-synchronizes-with</dfn> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> is a <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref>-provided <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">strict partial order</a></emu-xref> on <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref>-specific <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> that satisfies at least the following.</p>\n      <ul>\n        <li>If <var>eventA</var> host-synchronizes-with <var>eventB</var> in <var>execution</var>, <emu-xref aoid=\"HostEventSet\"><a href=\"/memory-model#sec-hosteventset\">HostEventSet</a></emu-xref>(<var>execution</var>) contains <var>eventA</var> and <var>eventB</var>.</li>\n        <li>There is no cycle in the union of host-synchronizes-with and <emu-xref href=\"/memory-model#sec-agent-order\"><a href=\"/memory-model#sec-agent-order\">is-agent-order-before</a></emu-xref> in <var>execution</var>.</li>\n      </ul>\n\n      <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n        <p>For two <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref>-specific events <var>eventA</var> and <var>eventB</var> in a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, <var>eventA</var> host-synchronizes-with <var>eventB</var> in <var>execution</var> implies <var>eventA</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>eventB</var> in <var>execution</var>.</p>\n      </div></emu-note>\n      <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n        <p>This <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> allows the <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref> to provide additional synchronization mechanisms, such as <code>postMessage</code> between HTML workers.</p>\n      </div></emu-note>\n    ","6.5":"<p>For a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, its <dfn>synchronizes-with</dfn> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> is the <emu-xref href=\"/ecmascript-data-types-and-values#least-relation\"><a href=\"/ecmascript-data-types-and-values#least-relation\">least Relation</a></emu-xref> on <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> that satisfies the following.</p>\n      <ul>\n        <li>\n          For events <var>readEvent</var> and <var>writeEvent</var>, <var>writeEvent</var> synchronizes-with <var>readEvent</var> in <var>execution</var> if <var>readEvent</var> <emu-xref href=\"/memory-model#sec-reads-from\"><a href=\"/memory-model#sec-reads-from\">reads-from</a></emu-xref> <var>writeEvent</var> in <var>execution</var>, <var>readEvent</var>.<var class=\"field\">[[Order]]</var> is <emu-const>seq-cst</emu-const>, <var>writeEvent</var>.<var class=\"field\">[[Order]]</var> is <emu-const>seq-cst</emu-const>, and <var>readEvent</var> and <var>writeEvent</var> have equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>.\n        </li>\n        <li>\n          For each element <var>eventsRecord</var> of <var>execution</var>.<var class=\"field\">[[EventsRecords]]</var>, the following is true.\n          <ul>\n            <li>For events <var>eventA</var> and <var>eventB</var>, <var>eventA</var> synchronizes-with <var>eventB</var> in <var>execution</var> if <var>eventsRecord</var>.<var class=\"field\">[[AgentSynchronizesWith]]</var> contains (<var>eventA</var>, <var>eventB</var>).</li>\n          </ul>\n        </li>\n        <li>For events <var>eventA</var> and <var>eventB</var>, <var>eventA</var> synchronizes-with <var>eventB</var> in <var>execution</var> if <var>eventA</var> <emu-xref href=\"/memory-model#sec-host-synchronizes-with\"><a href=\"/memory-model#sec-host-synchronizes-with\">host-synchronizes-with</a></emu-xref> <var>eventB</var> in <var>execution</var>.</li>\n      </ul>\n\n      <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n        <p>Owing to convention in <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref> literature, in a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">write events</a></emu-xref> synchronizes-with <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">read events</a></emu-xref>, instead of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">read events</a></emu-xref> synchronizes-with <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">write events</a></emu-xref>.</p>\n      </div></emu-note>\n\n      <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n        <p>In a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, <emu-const>init</emu-const> events do not participate in this <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> and are instead constrained directly by <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref>.</p>\n      </div></emu-note>\n\n      <emu-note data-num=\"3\"><span class=\"note\">Note 3</span><div class=\"note-contents\">\n        <p>In a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, not all <emu-const>seq-cst</emu-const> events related by <emu-xref href=\"/memory-model#sec-reads-from\"><a href=\"/memory-model#sec-reads-from\">reads-from</a></emu-xref> are related by synchronizes-with. Only events that also have equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref> are related by synchronizes-with.</p>\n      </div></emu-note>\n\n      <emu-note data-num=\"4\"><span class=\"note\">Note 4</span><div class=\"note-contents\">\n        <p>For <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block events</a></emu-xref> <var>readEvent</var> and <var>writeEvent</var> in a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var> such that <var>writeEvent</var> synchronizes-with <var>readEvent</var>, <var>readEvent</var> may <emu-xref href=\"/memory-model#sec-reads-from\"><a href=\"/memory-model#sec-reads-from\">reads-from</a></emu-xref> other writes than <var>writeEvent</var>.</p>\n      </div></emu-note>\n    ","6.6":"<p>For a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, its <dfn>happens-before</dfn> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> is the <emu-xref href=\"/ecmascript-data-types-and-values#least-relation\"><a href=\"/ecmascript-data-types-and-values#least-relation\">least Relation</a></emu-xref> on <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> that satisfies the following.</p>\n\n      <ul>\n        <li>\n          <p>For events <var>eventA</var> and <var>eventB</var>, <var>eventA</var> happens-before <var>eventB</var> in <var>execution</var> if any of the following conditions are true.</p>\n          <ul>\n            <li><var>eventA</var> <emu-xref href=\"/memory-model#sec-agent-order\"><a href=\"/memory-model#sec-agent-order\">is-agent-order-before</a></emu-xref> <var>eventB</var> in <var>execution</var>.</li>\n            <li><var>eventA</var> <emu-xref href=\"/memory-model#sec-synchronizes-with\"><a href=\"/memory-model#sec-synchronizes-with\">synchronizes-with</a></emu-xref> <var>eventB</var> in <var>execution</var>.</li>\n            <li><emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>) contains both <var>eventA</var> and <var>eventB</var>, <var>eventA</var>.<var class=\"field\">[[Order]]</var> is <emu-const>init</emu-const>, and <var>eventA</var> and <var>eventB</var> have overlapping <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>.</li>\n            <li>There is an event <var>eventC</var> such that <var>eventA</var> happens-before <var>eventC</var> and <var>eventC</var> happens-before <var>eventB</var> in <var>execution</var>.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>Because happens-before is a superset of <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>-order, a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> is consistent with the single-thread evaluation semantics of ECMAScript.</p>\n      </div></emu-note>\n    ","7.1":"<p>A <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var> has valid chosen reads if the following algorithm returns <emu-val>true</emu-val>.</p>\n      <emu-alg><ol><li>For each <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event <var>readEvent</var> of <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>), do<ol><li>Let <var>chosenValueRecord</var> be the element of <var>execution</var>.<var class=\"field\">[[ChosenValues]]</var> whose <var class=\"field\">[[Event]]</var> field is <var>readEvent</var>.</li><li>Let <var>chosenValue</var> be <var>chosenValueRecord</var>.<var class=\"field\">[[ChosenValue]]</var>.</li><li>Let <var>readValue</var> be <emu-xref aoid=\"ValueOfReadEvent\"><a href=\"/memory-model#sec-valueofreadevent\">ValueOfReadEvent</a></emu-xref>(<var>execution</var>, <var>readEvent</var>).</li><li>Let <var>chosenLength</var> be the number of elements in <var>chosenValue</var>.</li><li>Let <var>readLength</var> be the number of elements in <var>readValue</var>.</li><li>If <var>chosenLength</var> ≠ <var>readLength</var>, then<ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></li><li>If <var>chosenValue</var>[<var>i</var>] ≠ <var>readValue</var>[<var>i</var>] for some <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref> <var>i</var> in the <emu-xref href=\"/notational-conventions#interval\"><a href=\"/notational-conventions#interval\">interval</a></emu-xref> from 0 (inclusive) to <var>chosenLength</var> (exclusive), then<ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></li></ol></li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n    ","7.2":"<p>A <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var> has coherent reads if the following algorithm returns <emu-val>true</emu-val>.</p>\n      <emu-alg><ol><li>For each <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event <var>readEvent</var> of <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>), do<ol><li>Let <var>writes</var> be <emu-xref aoid=\"reads-bytes-from\"><a href=\"/memory-model#sec-reads-bytes-from\">reads-bytes-from</a></emu-xref>(<var>readEvent</var>) in <var>execution</var>.</li><li>Let <var>byteLocation</var> be <var>readEvent</var>.<var class=\"field\">[[ByteIndex]]</var>.</li><li>For each element <var>writeEvent</var> of <var>writes</var>, do<ol><li>If <var>readEvent</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>writeEvent</var> in <var>execution</var>, then<ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></li><li>If there exists a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event <var>value</var> that has <var>byteLocation</var> in its <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory range</a></emu-xref> such that <var>writeEvent</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>value</var> in <var>execution</var> and <var>value</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>readEvent</var> in <var>execution</var>, then<ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></li><li>Set <var>byteLocation</var> to <var>byteLocation</var> + 1.</li></ol></li></ol></li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n    ","7.3":"<p>A <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var> has tear free reads if the following algorithm returns <emu-val>true</emu-val>.</p>\n      <emu-alg><ol><li>For each <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event <var>readEvent</var> of <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>), do<ol><li>If <var>readEvent</var>.<var class=\"field\">[[NoTear]]</var> is <emu-val>true</emu-val>, then<ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: The remainder of dividing <var>readEvent</var>.<var class=\"field\">[[ByteIndex]]</var> by <var>readEvent</var>.<var class=\"field\">[[ElementSize]]</var> is 0.</li><li>For each <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory event</a></emu-xref> <var>writeEvent</var> such that <var>readEvent</var> <emu-xref href=\"/memory-model#sec-reads-from\"><a href=\"/memory-model#sec-reads-from\">reads-from</a></emu-xref> <var>writeEvent</var> in <var>execution</var> and <var>writeEvent</var>.<var class=\"field\">[[NoTear]]</var> is <emu-val>true</emu-val>, do<ol><li>If <var>readEvent</var> and <var>writeEvent</var> have equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref> and there exists a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory event</a></emu-xref> <var>value</var> such that <var>value</var> and <var>writeEvent</var> have equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>, <var>value</var>.<var class=\"field\">[[NoTear]]</var> is <emu-val>true</emu-val>, <var>writeEvent</var> and <var>value</var> are not the same <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block event</a></emu-xref>, and <var>readEvent</var> <emu-xref href=\"/memory-model#sec-reads-from\"><a href=\"/memory-model#sec-reads-from\">reads-from</a></emu-xref> <var>value</var> in <var>execution</var>, then<ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></li></ol></li></ol></li></ol></li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>A <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Shared Data Block event</a></emu-xref>'s <var class=\"field\">[[NoTear]]</var> field is <emu-val>true</emu-val> when that event was introduced via accessing an <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref> <emu-xref href=\"/ordinary-and-exotic-objects-behaviours#typedarray\"><a href=\"/ordinary-and-exotic-objects-behaviours#typedarray\">TypedArray</a></emu-xref>, and <emu-val>false</emu-val> when introduced via accessing a floating point <emu-xref href=\"/ordinary-and-exotic-objects-behaviours#typedarray\"><a href=\"/ordinary-and-exotic-objects-behaviours#typedarray\">TypedArray</a></emu-xref> or DataView.</p>\n        <p>Intuitively, this requirement says when a <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory range</a></emu-xref> is accessed in an aligned fashion via an <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref> <emu-xref href=\"/ordinary-and-exotic-objects-behaviours#typedarray\"><a href=\"/ordinary-and-exotic-objects-behaviours#typedarray\">TypedArray</a></emu-xref>, a single <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">write event</a></emu-xref> on that range must “win” when in a <emu-xref href=\"/memory-model#sec-data-races\"><a href=\"/memory-model#sec-data-races\">data race</a></emu-xref> with other <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">write events</a></emu-xref> with equal ranges. More precisely, this requirement says an aligned <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">read event</a></emu-xref> cannot read a value composed of bytes from multiple, different <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">write events</a></emu-xref> all with equal ranges. It is possible, however, for an aligned <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">read event</a></emu-xref> to read from multiple <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">write events</a></emu-xref> with overlapping ranges.</p>\n      </div></emu-note>\n    ","7.4":"<p>For a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var>, <dfn>is-memory-order-before</dfn> is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">strict total order</a></emu-xref> of all <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">Memory events</a></emu-xref> in <emu-xref aoid=\"EventSet\"><a href=\"/memory-model#sec-event-set\">EventSet</a></emu-xref>(<var>execution</var>) that satisfies the following.</p>\n      <ul>\n        <li>For events <var>eventA</var> and <var>eventB</var>, <var>eventA</var> is-memory-order-before <var>eventB</var> in <var>execution</var> if <var>eventA</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>eventB</var> in <var>execution</var>.</li>\n        <li>\n          <p>For events <var>readEvent</var> and <var>writeEvent</var> such that <var>readEvent</var> <emu-xref href=\"/memory-model#sec-reads-from\"><a href=\"/memory-model#sec-reads-from\">reads-from</a></emu-xref> <var>writeEvent</var> in <var>execution</var>, there is no <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event <var>value</var> in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>) such that <var>value</var>.<var class=\"field\">[[Order]]</var> is <emu-const>seq-cst</emu-const>, <var>writeEvent</var> is-memory-order-before <var>value</var> in <var>execution</var>, <var>value</var> is-memory-order-before <var>readEvent</var> in <var>execution</var>, and any of the following conditions are true.</p>\n          <ul>\n            <li><var>writeEvent</var> <emu-xref href=\"/memory-model#sec-synchronizes-with\"><a href=\"/memory-model#sec-synchronizes-with\">synchronizes-with</a></emu-xref> <var>readEvent</var> in <var>execution</var>, and <var>value</var> and <var>readEvent</var> have equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>.</li>\n            <li><var>writeEvent</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>readEvent</var> and <var>value</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>readEvent</var> in <var>execution</var>, <var>writeEvent</var>.<var class=\"field\">[[Order]]</var> is <emu-const>seq-cst</emu-const>, and <var>writeEvent</var> and <var>value</var> have equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>.</li>\n            <li><var>writeEvent</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>readEvent</var> and <var>writeEvent</var> <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <var>value</var> in <var>execution</var>, <var>readEvent</var>.<var class=\"field\">[[Order]]</var> is <emu-const>seq-cst</emu-const>, and <var>value</var> and <var>readEvent</var> have equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>.</li>\n          </ul>\n          <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n            <p>This clause additionally constrains <emu-const>seq-cst</emu-const> events on equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory ranges</a></emu-xref>.</p>\n          </div></emu-note>\n        </li>\n        <li>\n          <p>For each <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> event <var>writeEvent</var> in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>), if <var>writeEvent</var>.<var class=\"field\">[[Order]]</var> is <emu-const>seq-cst</emu-const>, then it is not the case that there is an infinite number of <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> or <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadModifyWriteSharedMemory</a></emu-xref> events in <emu-xref aoid=\"SharedDataBlockEventSet\"><a href=\"/memory-model#sec-sharedatablockeventset\">SharedDataBlockEventSet</a></emu-xref>(<var>execution</var>) with equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory range</a></emu-xref> that is memory-order before <var>writeEvent</var>.</p>\n          <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n            <p>This clause together with the forward progress guarantee on <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> ensure the liveness condition that <emu-const>seq-cst</emu-const> <emu-xref href=\"#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">writes</a></emu-xref> become visible to <emu-const>seq-cst</emu-const> <emu-xref href=\"#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">reads</a></emu-xref> with equal <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">memory range</a></emu-xref> in <emu-xref href=\"/ecmascript-data-types-and-values#finite\"><a href=\"/ecmascript-data-types-and-values#finite\">finite</a></emu-xref> time.</p>\n          </div></emu-note>\n        </li>\n      </ul>\n      <p>A <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> has sequentially consistent atomics if it admits an is-memory-order-before <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref>.</p>\n\n      <emu-note data-num=\"3\"><span class=\"note\">Note 3</span><div class=\"note-contents\">\n        <p>While is-memory-order-before includes all events in <emu-xref aoid=\"EventSet\"><a href=\"/memory-model#sec-event-set\">EventSet</a></emu-xref>(<var>execution</var>), those that are not constrained by <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> or <emu-xref href=\"/memory-model#sec-synchronizes-with\"><a href=\"/memory-model#sec-synchronizes-with\">synchronizes-with</a></emu-xref> in <var>execution</var> are allowed to occur anywhere in the order.</p>\n      </div></emu-note>\n    ","7.5":"<p>A <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <var>execution</var> is a valid execution (or simply an execution) if all of the following are true.</p>\n      <ul>\n        <li>The <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref> provides a <emu-xref href=\"/memory-model#sec-host-synchronizes-with\"><a href=\"/memory-model#sec-host-synchronizes-with\">host-synchronizes-with</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> for <var>execution</var>.</li>\n        <li><var>execution</var> admits a <emu-xref href=\"/memory-model#sec-happens-before\"><a href=\"/memory-model#sec-happens-before\">happens-before</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">Relation</a></emu-xref> that is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-set-and-relation-specification-type\">strict partial order</a></emu-xref>.</li>\n        <li><var>execution</var> has valid chosen reads.</li>\n        <li><var>execution</var> has coherent reads.</li>\n        <li><var>execution</var> has tear free reads.</li>\n        <li><var>execution</var> has sequentially consistent atomics.</li>\n      </ul>\n      <p>All programs have at least one valid execution.</p>\n    "};
export function Sec({ id }) {
  const html = sections[id] ?? '';
  return <div dangerouslySetInnerHTML={{ __html: html }} />;
}
